const safeUrl = (s:string) => /^https?:\/\//i.test(s||"") ? s : "#";
function ago(value:string|number) {
  const ms = new Date(value).getTime();
  if (!Number.isFinite(ms)) return "Récemment observée";
  const d = Math.max(0,Date.now()-ms);
  return d<60000 ? "À l’instant" : d<3600000 ? `Il y a ${Math.floor(d/60000)} min` : d<86400000 ? `Il y a ${Math.floor(d/3600000)} h` : `Il y a ${Math.floor(d/86400000)} j`;
}
function Logo(){return <span className="wordmark"><svg className="brand-icon" viewBox="0 0 32 32" fill="none" aria-hidden="true"><path d="M7 25V13a9 9 0 0 1 18 0v12M7 20h18M12 25h8" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round"/><path d="m16 7 4 6h-8z" fill="currentColor"/></svg>immoalert</span>;}
function Toggle({enabled,onChange,label,disabled=false}:{enabled:boolean;onChange:()=>void;label:string;disabled?:boolean}) {
  return <button className={`toggle ${enabled?"on":""}`} role="switch" aria-checked={enabled} aria-label={label} disabled={disabled} onClick={onChange}><i/><span className="sr-only">{enabled?"Activé":"Désactivé"}</span></button>;
}

